 static void Assert(bool condition,string message){if(!condition)throw new Exception(message);}
 static object Field(object obj,string name){return obj.GetType().GetField(name,BindingFlags.NonPublic|BindingFlags.Instance).GetValue(obj);}
 static SaleLine Line(string branch,string number,decimal sale,decimal profit,string type="FACTURA DE VENTA"){return new SaleLine{Date=new DateTime(2026,10,15),Dealer="DEMO",Branch=branch,Code=type.Contains("CREDITO")?"NC":"FA",Letter="A",Number=number,Type=type,Sector="Taller",Part="REPUESTO DEMO",Sale=sale,Profit=profit};}
 static void Entry(ZipArchive zip,string path,string xml){using(var writer=new StreamWriter(zip.CreateEntry(path).Open()))writer.Write(xml);}
 static void Xlsx(string path,string brand){using(var z=ZipFile.Open(path,ZipArchiveMode.Create)){Entry(z,"xl/workbook.xml","<workbook xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\"><sheets><sheet name=\"Reporte\" sheetId=\"1\" r:id=\"rId1\"/></sheets></workbook>");Entry(z,"xl/_rels/workbook.xml.rels","<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Target=\"worksheets/sheet1.xml\" Type=\"worksheet\"/></Relationships>");string header="",row="";var values=new Dictionary<string,string>{{"A","DEMO"},{"B","01"},{"C","100 - Taller Norte Autosur"},{"D",new DateTime(2026,10,15).ToOADate().ToString(System.Globalization.CultureInfo.InvariantCulture)},{"H","FACTURA DE VENTA"},{"I","FA"},{"J","A"},{"K","0001"},{"L",brand},{"Q","Taller"},{"BM","DEMO"},{"CA","1000"},{"CG","300"}};foreach(var v in new Dictionary<string,string>{{"D","Fecha emisión"},{"K","Número comprobante"},{"CA","Venta a precio final del repuesto"},{"CG","Utilidad"}})header+="<c r=\""+v.Key+"1\" t=\"inlineStr\"><is><t>"+v.Value+"</t></is></c>";foreach(var v in values)row+="<c r=\""+v.Key+"2\" t=\"inlineStr\"><is><t>"+v.Value+"</t></is></c>";Entry(z,"xl/worksheets/sheet1.xml","<worksheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\"><sheetData><row r=\"1\">"+header+"</row><row r=\"2\">"+row+"</row></sheetData></worksheet>");}}
 [STAThread]static void Main(){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);string root=Path.Combine(Path.GetTempPath(),"GeneralDemo_"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{
 DateTime p=new DateTime(2026,10,1);var cfg=new GeneralSettings(Path.Combine(root,"config"));cfg.Names["DEMO|01"]="Norte";cfg.Names["DEMO|02"]="Sur";cfg.SetTarget(p,"DEMO|01",700);cfg.SetTarget(p,"DEMO|02",700);cfg.SetMargin(p,22);cfg.Save();cfg=new GeneralSettings(Path.Combine(root,"config"));Assert(cfg.Target(p,"DEMO|01")==700&&cfg.Margin(p,0)==22,"No persiste objetivo por mes y sucursal");Assert(cfg.Target(p.AddMonths(1),"DEMO|01")==0,"Mezcla objetivos de meses");
 var lines=new List<SaleLine>{Line("01","1",500,150),Line("01","1",500,150),Line("01","2",-100,-20,"NOTA DE CREDITO"),Line("02","1",500,150)};var branches=GeneralMath.Branches(cfg,lines);var rows=GeneralMath.Rows(lines,branches,cfg,p,22,true,true,true);var total=GeneralMath.Total(rows,lines,branches.Select(b=>b.Key),p,22,true,true,true);Assert(total.Values.Sale==1400&&total.Values.Profit==430&&total.Values.Tickets==2,"Venta, utilidad o tickets no coinciden con núcleo existente");Assert(total.Values.Margin==SalesMath.Sum(lines).Margin,"Total promedia márgenes en vez de ponderar");Assert(rows[0].Advance>100&&total.Advance==100&&total.UtilityTarget==308&&total.UtilityDifference==-122,"Objetivo, diferencia o sobreperformance incorrectos");
 var one=GeneralMath.Rows(lines,branches.Take(1),cfg,p,22,true,true,true);var oneTotal=GeneralMath.Total(one,lines,branches.Take(1).Select(b=>b.Key),p,22,true,true,true);Assert(oneTotal.Values.Sale==900&&oneTotal.Target==700,"Filtro por sucursal mezcla otras bocas");var empty=GeneralMath.Total(new List<GeneralResult>(),lines,new string[0],p,22,true,true,true);Assert(empty.Values.Sale==0&&empty.Target==0&&empty.Advance==null,"Selección vacía mantiene cifras ocultas");
 lines.Add(Line("02","3",200,60,"INTERNA GARANTIA"));var without=GeneralMath.Rows(lines,branches,cfg,p,22,true,false,true);Assert(without.Sum(r=>r.Values.Sale)==1400,"No respeta interruptor Garantía del núcleo existente");Console.WriteLine("OK sucursales múltiples, NC, tickets únicos, margen ponderado, sin duplicar, sobreperformance y parámetros existentes");
 string fixture=Path.Combine(root,"report.xlsx");Xlsx(fixture,"RENAULT");var report=GeneralReport.Read(fixture,"RENAULT");Assert(report.Lines.Count==1&&report.Names["DEMO|01"]=="Norte","No reconoce sucursales del Excel");bool rejected=false;try{GeneralReport.Read(fixture,"NISSAN");}catch{rejected=true;}Assert(rejected,"Acepta reporte de otra marca");Console.WriteLine("OK lector del Excel existente sin cambiar cálculos; códigos de sucursal y marca");
 var original=new SalesStore(Path.Combine(root,"datos"));original.GetGoal(p).Total=12345;original.Set(new Snapshot{Period=p,Cutoff=p.AddDays(19),Loaded=DateTime.UtcNow,Source="original",Lines=new List<SaleLine>{Line("01","OLD",10,2)}});original.Save();string oldXml=File.ReadAllText(Path.Combine(original.Root,"objetivos.xml"));
 using(var form=new Form{Size=new Size(1440,900),Text="Demostración de Objetivo general"})using(var page=new GeneralPage(original.Root,"MARCA DEMO","RENAULT")){form.Controls.Add(page);form.Show();((DateTimePicker)Field(page,"period")).Value=p;var generalReport=new GeneralReport{Lines=lines,Names=new Dictionary<string,string>{{"DEMO|01","Norte"},{"DEMO|02","Sur"}}};var previous=Line("01","SEPT",200,40);previous.Date=new DateTime(2026,9,26);generalReport.Lines.Add(previous);page.ApplyReport(generalReport,"Reporte de demostración",false);page.ApplyReport(generalReport,"Reporte de demostración",false);var data=(SalesStore)Field(page,"data");Assert(data.Get(p).Lines.Count==5&&data.Get(p.AddMonths(-1))==null,"Carga repetida duplica o importa días fuera del cierre");page.ApplyReport(generalReport,"Reporte de demostración",true);Assert(data.Get(p.AddMonths(-1)).Lines.Count==1,"No importa otros cierres con elección explícita");Assert(File.ReadAllText(Path.Combine(original.Root,"objetivos.xml"))==oldXml,"El panel modifica las cargas u objetivos originales");
 var settings=(GeneralSettings)Field(page,"config");settings.SetTarget(p,"DEMO|01",700);settings.SetTarget(p,"DEMO|02",700);settings.Save();page.GetType().GetMethod("ReloadBranches",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(page,null);Application.DoEvents();var checks=(CheckedListBox)Field(page,"branches");Assert(checks.CheckedItems.Count==2,"No selecciona inicialmente todas las sucursales");checks.SetItemChecked(1,false);Application.DoEvents();var grid=(DataGridView)Field(page,"table");Assert(grid.Rows.Count==2&&((GeneralResult)Field(page,"total")).Values.Sale==900,"Tilde no actualiza filas y total");checks.SetItemChecked(0,false);Application.DoEvents();Assert(((GeneralResult)Field(page,"total")).Values.Sale==0&&!((Button)Field(page,"export")).Enabled,"Selección vacía permite exportar o conserva total");checks.SetItemChecked(0,true);checks.SetItemChecked(1,true);Application.DoEvents();
 var demoLines=new List<SaleLine>{Line("01","D1",60000000,15000000),Line("02","D2",30000000,8000000),Line("03","D3",20000000,6000000),Line("04","D4",45000000,12000000),Line("05","D5",48000000,12000000)};page.ApplyReport(new GeneralReport{Lines=demoLines,Names=new Dictionary<string,string>{{"DEMO|01","Norte"},{"DEMO|02","Sur"},{"DEMO|03","Centro"},{"DEMO|04","Oeste"},{"DEMO|05","Este"}}},"Demostración · valores ficticios",false);decimal[] demoTargets={85000000,25000000,35000000,55000000,110000000};for(int i=0;i<5;i++)settings.SetTarget(p,"DEMO|"+(i+1).ToString("00"),demoTargets[i]);settings.Save();page.GetType().GetMethod("ReloadBranches",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(page,null);page.GetType().GetMethod("SelectAll",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(page,new object[]{true});Application.DoEvents();Assert(((GeneralResult)Field(page,"total")).Values.Sale==203000000,"Demostración con cinco sucursales no suma correctamente");
 using(var image=GeneralPanel.Image("MARCA DEMO",p,p.AddDays(24),(List<GeneralResult>)Field(page,"displayed"),(GeneralResult)Field(page,"total"))){Assert(image.Width>1400&&image.Height>250,"Panel exportado incompleto");image.Save("objetivo-general-panel.png");}
 using(var shot=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(shot,new Rectangle(0,0,shot.Width,shot.Height));shot.Save("objetivo-general-pantalla.png");}form.Size=new Size(1100,760);Application.DoEvents();Assert(grid.Width>600&&grid.Height>200,"Panel no se adapta al tamaño mínimo");page.GetType().GetMethod("ShowPanel",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(page,new object[]{null,EventArgs.Empty});Application.DoEvents();var preview=(GeneralPreview)Field(page,"preview");Assert(preview.Visible&&form.Enabled,"La vista del panel bloquea la app");preview.Close();Assert(!form.IsDisposed&&form.Enabled,"Cerrar panel cierra la app");form.Close();}
 Console.WriteLine("OK historial general independiente, cierres 27–26, repetición sin duplicados, tildes y exportación PNG");Console.WriteLine("Pruebas de Objetivo general aprobadas.");
 }finally{Directory.Delete(root,true);}}
